         'それが本問の分類軸である。<br>'
         '<span class="kw4">禁忌①感染を持ち込むもの：活動性の全身感染症（敗血症）、'
         'B型・C型肝炎、HIV、HTLV-1、活動性結核、狂犬病</span>。'
         '<span class="kw4">禁忌②細胞そのものが全身を巡っているもの：白血病・悪性リンパ腫などの造血器悪性腫瘍</span>。'
         '<span class="kw4">禁忌③滅菌が効かないもの：Creutzfeldt-Jakob病などのプリオン病、'
