        '<tr><td><span class="kw4">滅菌が効かない</span></td>'
        '<td><span class="kw4">Creutzfeldt-Jakob病・原因不明の中枢神経疾患／認知症</span></td>'
        '<td><span class="kw4">プリオンは通常の滅菌で不活化されない</span></td></tr>'
        '<tr><td><span class="kw4">眼局所の問題</span></td>'
        '<td><span class="kw4">眼内悪性腫瘍・眼内炎・角膜混濁・眼内手術の既往</span></td>'
        '<td><span class="kw4">移植片として使えない</span></td></tr>'
        '<tr><td><span class="kw3">禁忌でない</span></td>'
        '<td><span class="kw3">乳癌・胃癌・肺癌などの固形癌／高齢／屈折異常（近視・遠視）</span></td>'
