         '<span class="kw4">③神経筋接合部：重症筋無力症。日内変動（夕方増悪）・易疲労性・'
         'アイスパック試験やテンシロン試験で改善するのが決め手</span>。<br>'
         '<span class="kw4">④筋原性：慢性進行性外眼筋麻痺〈CPEO〉、筋強直性ジストロフィー、眼咽頭型筋ジストロフィー</span>。<br>'
         '<span class="kw4">⑤先天性：挙筋の形成不全。弱視（形態覚遮断）の原因になるため早期手術の適応</span>。<br>'
         '<span class="kw4">⑥機械性：腫瘍・瘢痕・浮腫が瞼を物理的に押し下げる</span>。<br>'
