        '<span class="kw4">正答率34%と本章で最も低い</span>のは、'
        '<span class="kw4">「甲状腺眼症＝眼が目立つ＝眼瞼の異常」と大ざっぱに結び付けて c を選んでしまう</span>ことと、'
