         '<span class="kw3">代表はトロピカミド（作用時間4〜6時間・抗コリン薬）と'
         'フェニレフリン（交感神経刺激薬・瞳孔散大筋を収縮させる）で、'
         '両者の配合点眼薬が実地では多く用いられる</span>。'
         '<span class="kw3">小児の屈折検査に用いるアトロピンやシクロペントラートは'
