         '<span class="kw3">眼底検査（とくに双眼倒像鏡による周辺部観察）、蛍光眼底造影〈FA・IA〉、'
         '網膜剝離／裂孔の検索、糖尿病網膜症の評価、未熟児網膜症のスクリーニング、'
         '白内障や硝子体手術の術前評価</span>である。<br>'
         '<span class="kw4">逆に散瞳してはいけない／不要な検査もはっきりしている</span>——'
