                     '<span class="kw3">頭部装着型の光源と手持ちの集光レンズ（＋20Dなど）を用い、'
                     '倒像（上下左右が反転した像）を観察する</span>。'
                     '<span class="kw3">倍率は低いが視野が広く、強膜圧迫を併用すれば最周辺部まで観察できる</span>ため、'
