        '<tr><td>倍率</td><td><span class="kw">高い（約15倍）</span></td>'
        '<td>低い（約3倍）</td><td>高い</td></tr>'
        '<tr><td>視野</td><td>狭い（後極部のみ）</td><td><span class="kw3">広い（周辺まで）</span></td>'
