        '<tr><td><span class="kw3">立体視</span></td><td><span class="kw4">できない（片眼）</span></td>'
        '<td><span class="kw3">できる（両眼）</span></td><td><span class="kw3">できる（両眼）</span></td></tr>'
        '<tr><td>主な用途</td><td>乳頭・後極部のスクリーニング</td>'
        '<td><span class="kw3">網膜剝離・裂孔・未熟児網膜症・光凝固</span></td>'
