        '<span class="kw">「立体的」＝両眼で見る＝双眼倒像鏡</span>という短絡で解ける。'
        '<span class="kw4">「倒像鏡」の語感から「像が逆さま＝見にくい」と考えて避けてしまうと落とす</span>が、'
        '<span class="kw">臨床では周辺部まで立体的に見られる倒像鏡のほうが'
