                     '<span class="kw3">麻痺筋の作用方向で偏位が大きくなり、'
                     '患眼側の図は小さく、健眼側の図は大きく描かれる</span>。'
                     '<span class="kw3">交通事故後なら眼窩吹き抜け骨折による外眼筋の絞扼や'
