         'その光路上にある混濁を「影絵」として観察する方法</span>である。'
         '<span class="kw3">細隙灯顕微鏡や直像鏡で、光軸をほぼ視軸に合わせて観察する</span>。<br>'
         '<span class="kw3">この方法が威力を発揮するのは中間透光体（角膜・前房・水晶体・硝子体）の混濁</span>で、'
