         '先天白内障・網膜芽細胞腫・未熟児網膜症・第一次硝子体過形成遺残などを疑い緊急に精査する</span>。'
         '<span class="kw4">網膜芽細胞腫は生命に関わるため、白色瞳孔を見たら即座に眼科紹介である</span>。<br>'
         '<span class="kw">白内障の分類と背景も押さえておく</span>：'
