         '<span class="kw">硝子体基底部（鋸状縁付近）で最も強固に、'
         '次いで視神経乳頭縁・黄斑部・網膜血管に沿って強く接着する</span>。'
         '<span class="kw3">加齢に伴い、ヒアルロン酸が水を保持できなくなって'
         'ゲルが崩れる（液化）と、硝子体は網膜から剝がれる＝後部硝子体剝離〈PVD〉</span>が起こる。'
         '<span class="kw3">このとき生じる症状が飛蚊症（濁りの影が飛んで見える）と'
         '光視症（網膜が牽引されて光を感じる）である</span>。<br>'
         '<span class="kw4">臨床上決定的に重要なのは、剝がれる際に接着の強い部位で'
         '網膜が引き裂かれて網膜裂孔ができうること</span>である。'
         '<span class="kw4">裂孔から液化硝子体が網膜下へ流入すると裂孔原性網膜剝離になる</span>。'
