        '<tr><td><span class="kw3">硝子体</span></td>'
        '<td><span class="kw3">水99%＋Ⅱ型コラーゲン・ヒアルロン酸1%</span></td>'
        '<td><span class="kw3">眼球容積の約80%。無血管・無神経</span></td></tr>'
        '<tr><td><span class="kw4">水晶体</span></td>'
        '<td><span class="kw4">水約65%＋クリスタリン約35%</span></td>'
        '<td><span class="kw4">生体で最も蛋白濃度が高い組織の1つ。混濁＝白内障</span></td></tr>'
        '<tr><td>角　膜</td><td>水約78%＋Ⅰ型コラーゲン</td>'
        '<td><span class="kw">無血管。内皮のポンプで脱水を保つ</span>（NO.19）</td></tr>'
