        '<tr><td>脈絡膜</td><td>血管・色素</td><td>網膜外層への栄養供給。血流量が多い</td></tr></table>'
        '<span class="kw">「透明な組織はどれも水が多い」が、'
        '硝子体と水晶体では桁が違う（99% vs 65%）</span>。'
        '<span class="kw">水晶体は屈折力を持つために高濃度の蛋白を必要とし、'
