        '<tr><td>③</td><td>赤緑試験（二色テスト）</td>'
        '<td><span class="kw">色収差を利用した球面度数の微調整（赤が良い＝低矯正／緑が良い＝過矯正）</span></td></tr>'
        '<tr><td>④</td><td>点状指標</td><td>固視の目印などの補助</td></tr>'
        '<tr><td><span class="kw3">⑤</span></td><td><span class="kw3">乱視表（放射線視標）</span></td>'
