         '<span class="kw4">三徴として押さえる</span>——'
         '<span class="kw4">①複視（筋の嵌頓による眼球運動制限。上方視で悪化することが多い）、'
         '②眼球陥凹（眼窩容積が増えて眼球が後退する。急性期は腫脹で隠れ、'
         '腫れが引いてから明らかになる）、'
         '③頰部・上唇・上顎歯肉の知覚低下（眼窩下溝を走る眼窩下神経＝三叉神経第2枝の障害）</span>。'
