         '完全矯正眼鏡で調節量が減れば輻湊も減り、遠見・近見ともに正位になる。最も多い</span>。<br>'
         '<span class="kw3">②非屈折性調節性内斜視（高AC/A比型）：'
         '調節量は普通でも、1Dの調節に対する輻湊が過大な型。'
         '遠見では正位だが、調節を要する近見でだけ内斜する</span>。'
         '<span class="kw3">対処は二重焦点眼鏡（近用部に加入を入れて近見時の調節を減らす）で、'
