         '<span class="kw3">③部分調節性内斜視：完全矯正眼鏡で軽快するが偏位が残る型。'
         '残った分に対して手術（内直筋後転など）を行う</span>。<br>'
         '<span class="kw">縮瞳薬（ピロカルピン等）が理屈のうえで効くのは、'
         '毛様体筋を薬理学的に直接収縮させることで、'
