         '<span class="kw3">判断の軸は変わらず「移植片とともにレシピエントへ'
         '何かを持ち込むおそれがあるか」の一点である</span>。<br>'
         '<span class="kw3">角膜が無血管組織であること（免疫特権）から、'
         'HLA適合を厳密に問わず、心停止後の提供が可能である</span>。'
         '<span class="kw3">これがアイバンクという仕組みを成り立たせている</span>。'
         '<span class="kw3">同じ理由で、血行性転移が角膜に及ばない固形癌は禁忌にならない</span>。<br>'
