         'この時期を逃すと不可逆的な弱視となる</span>。'
         '<span class="kw3">視軸を遮る先天白内障では、'
         '両眼性なら生後6〜10週までに、片眼性はさらに早期に手術を行う</span>。'
         '<span class="kw3">術後は無水晶体眼となるので、'
         'コンタクトレンズや眼鏡による光学的矯正を直ちに開始し、'
